<!-- 文件作用：按先行设计维护Markdown文章，保留版本冲突草稿并使用服务端安全预览和官方用途上传。 -->
<template>
  <AppShell :title="articleId?'编辑文章':'新建文章'" back>
    <view v-if="error" class="error-box article-error" @click="load">{{ error }} · 点击重试</view>
    <EmptyState v-if="state.ready&&state.user?.role!=='admin'" title="仅平台管理员可访问" detail="文章编辑与发布仅向平台管理员开放。" icon="shield"/>
    <view v-else-if="loading||!loaded&&!error" class="loading-line">正在读取文章…</view>
    <template v-else-if="loaded&&state.user?.role==='admin'">
      <view class="article-tabs"><button class="article-tab" :class="{'article-tab-active':mode==='edit'}" :disabled="busy||uploading" @click="selectMode('edit')">编辑</button><button class="article-tab" :class="{'article-tab-active':mode==='preview'}" :disabled="busy||uploading" @click="selectMode('preview')">{{previewing?'预览中…':'预览'}}</button></view>
      <view v-if="conflict" class="article-conflict"><text class="article-conflict-copy">{{conflict}}</text><view class="article-conflict-actions"><button class="text-btn" @click="copyDraft">复制本地草稿</button><button class="text-btn" :disabled="busy||uploading" @click="reloadLatest">读取最新版本</button></view></view>
      <template v-if="mode==='edit'">
        <view class="field article-field"><view class="article-field-heading"><text class="field-label">文章标题</text><text class="article-counter" :class="{'article-counter-invalid':charCount(form.title)>60}">{{charCount(form.title)}} / 60</text></view><input v-model="form.title" class="input" :maxlength="-1" :disabled="busy||uploading" placeholder="2—60个字的文章标题"/></view>
        <view class="field article-field"><view class="article-field-heading"><text class="field-label">摘要</text><text class="article-counter" :class="{'article-counter-invalid':charCount(form.summary)>300}">{{charCount(form.summary)}} / 300</text></view><textarea v-model="form.summary" class="input article-summary" :maxlength="-1" :disabled="busy||uploading" placeholder="选填，最多300个字"/></view>
        <view class="article-field"><view class="article-field-heading"><text class="field-label">封面图（选填）</text><text class="article-counter">16:9 · 不超过3MB</text></view><view class="article-cover-row"><view v-if="form.cover_url" class="article-cover"><image class="article-cover-image" :src="assetUrl(form.cover_url)" mode="aspectFill"/><button class="article-remove" aria-label="移除封面" :disabled="busy||uploading" @click="form.cover_url='' "><Icon name="close" :size="14"/></button></view><button class="article-cover-choice" :disabled="busy||uploading" @click="uploadImage('article_cover')"><Icon name="photo" :size="24"/><text>{{uploading?'图片处理中…':form.cover_url?'更换封面':'选择封面'}}</text></button></view></view>
        <view class="article-field"><view class="article-field-heading"><text class="field-label">正文（Markdown）</text><button class="text-btn article-insert" :disabled="busy||uploading" @click="uploadImage('article_image')"><Icon name="photo" :size="14"/>插入图片</button></view><textarea v-model="form.body_markdown" class="input article-source" :maxlength="-1" :disabled="busy||uploading" placeholder="使用Markdown编写正文，支持标题、列表与平台插图" @blur="rememberCursor"/><view class="article-field-heading article-body-hint"><text class="article-counter">插图最多20张，保留原比例</text><text class="article-counter" :class="{'article-counter-invalid':bodyBytes>MAX_BODY_BYTES}">{{bodyBytes}} / 49152字节</text></view></view>
      </template>
      <view v-else class="article-preview"><view v-if="previewError" class="error-box" @click="refreshPreview">{{previewError}} · 点击重试</view><view v-else-if="previewing" class="loading-line">正在安全解析正文…</view><template v-else><image v-if="form.cover_url" class="article-preview-cover" :src="assetUrl(form.cover_url)" mode="widthFix"/><text class="article-preview-title">{{form.title||'未填写文章标题'}}</text><text v-if="form.summary" class="article-preview-summary">{{form.summary}}</text><ArticleBody :html="previewHTML"/></template></view>
      <view class="article-state"><text class="field-label">文章状态</text><view class="article-status-options"><button v-for="item in statusOptions" :key="item.value" class="article-status" :class="{'article-status-selected':form.status===item.value}" :disabled="busy||uploading" @click="form.status=item.value"><Icon :name="form.status===item.value?'check':'circle'" :size="14"/><text>{{item.label}}</text></button></view></view>
      <view class="action-footer article-actions"><button class="btn-secondary article-save" :disabled="busy||uploading" @click="save('draft')">{{busy?'保存中…':'保存草稿'}}</button><button class="btn article-save" :disabled="busy||uploading" @click="save(form.status==='hidden'?'hidden':'published')">{{busy?'保存中…':form.status==='hidden'?'保存并下架':'发布文章'}}</button></view>
    </template>
  </AppShell>
</template>
<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import AppShell from '../../../components/AppShell.vue'
import EmptyState from '../../../components/EmptyState.vue'
import Icon from '../../../components/Icon.vue'
import ArticleBody from '../../../components/ArticleBody.vue'
import {getAdminArticle,createArticle,updateArticle,previewArticle} from '../../../api/content.api'
import {errorMessage,errorStatus,isCancelled,token} from '../../../api/client'
import {state,init,sessionRevision} from '../../../lib/store'
import {chooseUploadImage} from '../../../lib/media'
import {assetUrl,notify} from '../../../lib/format'
import type {AdminArticle,ArticleInput,ArticleStatus} from '../../../types/content'

const MAX_BODY_BYTES=48*1024
const statusOptions:ReadonlyArray<{value:ArticleStatus;label:string}>=[{value:'draft',label:'草稿'},{value:'published',label:'已发布'},{value:'hidden',label:'已下架'}]
const form=reactive<ArticleInput>({title:'',summary:'',body_markdown:'',cover_url:'',status:'draft'}),articleId=ref(''),loaded=ref(false),loading=ref(false),busy=ref(false),uploading=ref(false),error=ref(''),conflict=ref(''),mode=ref<'edit'|'preview'>('edit'),previewHTML=ref(''),previewError=ref(''),previewing=ref(false)
const bodyBytes=computed(()=>byteCount(form.body_markdown))
let visible=false,disposed=false,loadVersion=0,previewVersion=0,uploadVersion=0,writeVersion=0,cursor=-1,loadedSession:ReturnType<typeof currentSession>|null=null
/** 捕获账号、平台权限及认证修订，管理员更换或失权后不回填旧文章。 */
function currentSession(){return{id:state.user?.id,role:state.user?.role,adminRole:state.user?.platform_admin_role,status:state.user?.status,token:token(),revision:sessionRevision()}}
/** 只有同一有效平台管理员可接收编辑结果，最终权限由服务端确认。 */
function sameSession(session:ReturnType<typeof currentSession>|null):boolean{return !!session&&state.user?.role==='admin'&&state.user.status!=='frozen'&&session.id===state.user.id&&session.role===state.user.role&&session.adminRole===state.user.platform_admin_role&&session.status===state.user.status&&session.token===token()&&session.revision===sessionRevision()}
/** 与后端Unicode字符限制保持一致，避免表情被按两个字符误算。 */
function charCount(value:string):number{return Array.from(value).length}
/** 计算真实UTF-8字节，微信环境不依赖TextEncoder。 */
function byteCount(value:string):number{return Array.from(value).reduce((total,char)=>{const point=char.codePointAt(0)||0;return total+(point<=0x7f?1:point<=0x7ff?2:point<=0xffff?3:4)},0)}
/** 当前账号失效时清除私有草稿和所有迟到操作，而不保留其它管理员原稿。 */
function clear():void{loadVersion++;previewVersion++;uploadVersion++;writeVersion++;Object.assign(form,{title:'',summary:'',body_markdown:'',cover_url:'',status:'draft',revision:undefined});loaded.value=false;loading.value=false;busy.value=false;uploading.value=false;previewing.value=false;previewHTML.value='';previewError.value='';error.value='';conflict.value='';mode.value='edit';loadedSession=null;cursor=-1}
/** 成功保存使用服务器修订与原稿，后续继续编辑同一篇而不重复创建。 */
function apply(article:AdminArticle):void{articleId.value=article.id;Object.assign(form,{title:article.title,summary:article.summary,body_markdown:article.body_markdown,cover_url:article.cover_url,status:article.status,revision:article.revision});loaded.value=true;loadedSession=currentSession();conflict.value=''}
/** 冷启动先恢复身份，再读取既有稿件；读取失败不显示旧账号或缺失文章。 */
async function load():Promise<void>{if(!visible||busy.value||uploading.value)return;const current=++loadVersion;loading.value=true;error.value='';let session:ReturnType<typeof currentSession>|null=null;try{await init();if(!visible||current!==loadVersion)return;if(state.user?.role!=='admin'||state.user.status==='frozen'){clear();return}session=currentSession();if(!articleId.value){loaded.value=true;loadedSession=session;return}const result=await getAdminArticle(articleId.value);if(visible&&current===loadVersion&&sameSession(session))apply(result)}catch(err){if(visible&&current===loadVersion&&(!session||sameSession(session))){if([401,403,404].includes(errorStatus(err)||0))clear();error.value=errorMessage(err)}}finally{if(current===loadVersion)loading.value=false}}
/** 保存时保留多行正文，仅将标题做服务端同样的首尾空白处理。 */
function articleBody(status:ArticleStatus):ArticleInput{const title=form.title.trim();if(charCount(title)<2||charCount(title)>60)throw new Error('文章标题需要2—60个字');if(charCount(form.summary)>300)throw new Error('文章摘要最多300个字');if(!form.body_markdown.trim()||bodyBytes.value>MAX_BODY_BYTES)throw new Error('Markdown正文不能为空且不能超过48KiB');return{title,summary:form.summary,body_markdown:form.body_markdown,cover_url:form.cover_url,status,...(articleId.value?{revision:form.revision}:{})}}
/** 独占保存请求；冲突保留原稿，失权清空，旧账号结果不能覆盖或提示新账号。 */
async function save(status:ArticleStatus):Promise<void>{if(busy.value||uploading.value||!loaded.value||!sameSession(loadedSession))return;let body:ArticleInput;try{body=articleBody(status)}catch(err){notify(err);return}const session=currentSession(),id=articleId.value,current=++writeVersion;busy.value=true;conflict.value='';try{const result=id?await updateArticle(id,body):await createArticle(body);if(!disposed&&current===writeVersion&&sameSession(session)){apply(result);if(visible)notify(status==='published'?'文章已发布':status==='hidden'?'文章已下架':'草稿已保存')}}catch(err){if(!disposed&&current===writeVersion&&sameSession(session)){if(errorStatus(err)===409)conflict.value='文章已由其他管理员更新，本地草稿已保留。请复制草稿后读取最新版本并合并。';else if([401,403,404].includes(errorStatus(err)||0)){clear();error.value=errorMessage(err)}else if(visible)notify(err)}}finally{if(current===writeVersion)busy.value=false}}
/** 预览仅解析当前正文，不保存；新的正文、切页或账号会使旧预览失效。 */
async function refreshPreview():Promise<void>{if(!visible||busy.value||uploading.value||!loaded.value||!sameSession(loadedSession))return;const body=form.body_markdown;if(!body.trim()||byteCount(body)>MAX_BODY_BYTES){previewError.value='Markdown正文不能为空且不能超过48KiB';return}const current=++previewVersion,session=currentSession();previewing.value=true;previewError.value='';previewHTML.value='';try{const result=await previewArticle(body);if(visible&&current===previewVersion&&sameSession(session)&&form.body_markdown===body)previewHTML.value=result.body_html}catch(err){if(visible&&current===previewVersion&&sameSession(session)){if([401,403].includes(errorStatus(err)||0)){clear();error.value=errorMessage(err)}else previewError.value=errorMessage(err)}}finally{if(current===previewVersion)previewing.value=false}}
/** 编辑与预览由明确点击切换，预览使用安全服务端结果。 */
function selectMode(value:'edit'|'preview'):void{if(busy.value||uploading.value)return;mode.value=value;if(value==='preview')void refreshPreview();else{previewVersion++;previewing.value=false}}
/** 记住官方textarea光标，用于原生选图返回后在原位置插入Markdown。 */
function rememberCursor(event:unknown):void{const detail=event&&typeof event==='object'&&'detail'in event?event.detail:null,target=event&&typeof event==='object'&&'target'in event?event.target:null;if(detail&&typeof detail==='object'&&'cursor'in detail&&typeof detail.cursor==='number')cursor=detail.cursor;else if(target&&typeof target==='object'&&'selectionStart'in target&&typeof target.selectionStart==='number')cursor=target.selectionStart;else cursor=-1}
/** 官方按用途裁剪压缩后上传，原生选图隐藏不丢草稿，切号或卸载不回填。 */
async function uploadImage(purpose:'article_cover'|'article_image'):Promise<void>{if(busy.value||uploading.value||!loaded.value||!sameSession(loadedSession))return;const session=currentSession(),current=++uploadVersion;uploading.value=true;try{const url=await chooseUploadImage(purpose);if(disposed||current!==uploadVersion||!sameSession(session))return;if(purpose==='article_cover')form.cover_url=url;else{const insertion='\n![图片说明]('+url+')\n',position=cursor<0?form.body_markdown.length:Math.min(cursor,form.body_markdown.length),next=form.body_markdown.slice(0,position)+insertion+form.body_markdown.slice(position);if(byteCount(next)>MAX_BODY_BYTES){notify('插入后正文超过48KiB，请缩短正文后重试');return}form.body_markdown=next;cursor=position+insertion.length}}catch(err){if(!disposed&&current===uploadVersion&&sameSession(session)&&!isCancelled(err))notify(err)}finally{if(current===uploadVersion)uploading.value=false}}
/** 复制完整本地标题、摘要及原稿，读取服务器新版前可自行保存和合并。 */
function copyDraft():void{uni.setClipboardData({data:'# '+form.title+'\n\n'+form.summary+'\n\n'+form.body_markdown})}
/** 只有明确确认后才替换冲突草稿，取消仍保持全部本地编辑。 */
async function reloadLatest():Promise<void>{if(busy.value||uploading.value||!sameSession(loadedSession))return;const session=currentSession();try{const result=await uni.showModal({title:'读取最新版本',content:'将替换当前未保存内容，建议先复制本地草稿。是否继续？',confirmText:'读取最新',cancelText:'保留草稿'});if(result.confirm&&visible&&sameSession(session))await load()}catch(err){if(visible&&sameSession(session))notify(err)}}
/** 相同账号原生选图返回保留表单，不用下拉刷新重置草稿。 */
function showPage():void{visible=true;if(loaded.value&&sameSession(loadedSession)){if(mode.value==='preview'&&!previewHTML.value&&!previewError.value)void refreshPreview();return}if(!loading.value)void load()}
/** 隐藏停止读取与预览，保存及选图保持原操作锁直到返回，避免重复写入。 */
function hidePage():void{visible=false;loadVersion++;previewVersion++;loading.value=false;previewing.value=false}
watch(()=>form.body_markdown,()=>{previewVersion++;previewing.value=false;previewHTML.value='';previewError.value=''})
watch([()=>state.user?.id,()=>state.user?.role,()=>state.user?.platform_admin_role,()=>state.user?.status,sessionRevision],()=>{clear();if(visible)void load()})
onLoad(options=>{articleId.value=options?.id||''})
onShow(showPage)
onHide(hidePage)
onUnload(()=>{disposed=true;hidePage();clear()})
</script>
<style scoped>
.article-error{margin-bottom:30.7692rpx}.article-tabs{display:flex;min-width:0;margin-bottom:38.4615rpx;border:1px solid var(--line);border-radius:7.6923rpx;overflow:hidden}.article-tab{display:flex;align-items:center;justify-content:center;flex:1;min-width:0;min-height:69.2308rpx;padding:11.5385rpx 15.3846rpx;border:0;border-radius:3.8462rpx;background:transparent;color:var(--muted);font-size:26.9231rpx;line-height:1.4}.article-tab-active{background:var(--accent);color:var(--bg);font-weight:600}.article-field{margin-bottom:38.4615rpx}.article-field-heading{display:flex;align-items:center;justify-content:space-between;gap:15.3846rpx;min-width:0;margin-bottom:11.5385rpx}.article-counter{flex-shrink:0;font-size:21.1538rpx;line-height:34.6154rpx;color:var(--muted)}.article-counter-invalid{color:#e9b69d}.article-summary{height:153.8462rpx}.article-cover-row{display:flex;align-items:stretch;gap:15.3846rpx;min-width:0}.article-cover{position:relative;flex:1;min-width:0;aspect-ratio:16/9;border-radius:7.6923rpx;overflow:hidden}.article-cover-image{position:absolute;inset:0;display:block;width:100%;height:100%}.article-remove{position:absolute;top:7.6923rpx;right:7.6923rpx;display:flex;align-items:center;justify-content:center;width:53.8462rpx;height:53.8462rpx;padding:0;border:0;border-radius:50%;background:rgba(10,19,17,.72);color:#fff}.article-cover-choice{display:flex;flex:1;align-items:center;justify-content:center;flex-direction:column;gap:11.5385rpx;min-width:0;min-height:165.3846rpx;padding:23.0769rpx;border:1px dashed var(--line);border-radius:7.6923rpx;background:transparent;color:var(--muted);font-size:25rpx;line-height:1.5}.article-insert{min-height:53.8462rpx;padding:0;font-size:23.0769rpx}.article-source{height:376.9231rpx;font-family:monospace;font-size:25rpx;line-height:42.3077rpx}.article-body-hint{flex-wrap:wrap;margin-top:11.5385rpx}.article-state{padding:7.6923rpx 0 0}.article-status-options{display:flex;gap:15.3846rpx;margin-top:15.3846rpx;min-width:0}.article-status{display:flex;align-items:center;justify-content:center;flex:1;gap:11.5385rpx;min-width:0;min-height:61.5385rpx;padding:11.5385rpx 7.6923rpx;border:1px solid var(--line);border-radius:7.6923rpx;background:transparent;color:var(--muted);font-size:23.0769rpx;line-height:1.4}.article-status-selected{border-color:var(--accent);color:var(--accent)}.article-actions{display:flex;gap:15.3846rpx;margin-top:23.0769rpx}.article-save{flex:1;min-width:0}.article-preview{padding:0 0 38.4615rpx;min-height:384.6154rpx}.article-preview-cover{display:block;width:100%;height:auto;aspect-ratio:16/9;border-radius:7.6923rpx;margin-bottom:30.7692rpx}.article-preview-title{display:block;margin-bottom:23.0769rpx;font-size:38.4615rpx;font-weight:700;line-height:1.5;overflow-wrap:anywhere}.article-preview-summary{display:block;margin-bottom:30.7692rpx;color:var(--muted);font-size:26.9231rpx;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.article-conflict{padding:23.0769rpx 0;margin-bottom:30.7692rpx;border-bottom:1px solid var(--line)}.article-conflict-copy{display:block;color:#e9b69d;font-size:25rpx;line-height:1.8;overflow-wrap:anywhere}.article-conflict-actions{display:flex;justify-content:space-between;gap:15.3846rpx;min-width:0;margin-top:11.5385rpx}
</style>
